import{c as r,Q as a,j as s,m as o}from"./chunks/framework.Ce_49mA8.js";const h=JSON.parse('{"title":"Толщина кожи для кошелька, сумки и ремня: таблица подбора","description":"Справочник мастера: точная таблица толщин кожи под изделия, разница темпера и дубления, перевод унций oz в мм, правила шерфования и контроль разнотолщинности.","frontmatter":{"title":"Толщина кожи для кошелька, сумки и ремня: таблица подбора","description":"Справочник мастера: точная таблица толщин кожи под изделия, разница темпера и дубления, перевод унций oz в мм, правила шерфования и контроль разнотолщинности.","datePublished":"2026-11-14","dateModified":"2026-11-15","tags":["Толщина кожи","Кожевенное дело","Свойства кожи","Складской учёт"],"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Толщина кожи для кошелька, сумки и ремня: таблица подбора"}],["meta",{"property":"og:description","content":"Справочник мастера: точная таблица толщин кожи под изделия, разница темпера и дубления, перевод унций oz в мм, правила шерфования и контроль разнотолщинности."}],["meta",{"property":"og:url","content":"https://omnicraft-erp.com/ru/articles/tolshchina-kozhi-dlya-izdelij"}],["meta",{"property":"og:image","content":"https://omnicraft-erp.com/img/ru/calculators/leather-cost-calculator-og.webp"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"Article\\",\\"headline\\":\\"Толщина кожи для кошелька, сумки и ремня: таблица подбора\\",\\"description\\":\\"Справочник мастера: точная таблица толщин кожи под изделия, разница темпера и дубления, перевод унций oz в мм, правила шерфования и контроль разнотолщинности.\\",\\"image\\":[\\"https://omnicraft-erp.com/img/ru/calculators/leather-cost-calculator-og.webp\\"],\\"inLanguage\\":\\"ru-RU\\",\\"mainEntityOfPage\\":\\"https://omnicraft-erp.com/ru/articles/tolshchina-kozhi-dlya-izdelij\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"ОмниКрафт ЕРП\\",\\"url\\":\\"https://omnicraft-erp.com/ru/\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"ОмниКрафт ЕРП\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://omnicraft-erp.com/logo.svg\\"}},\\"datePublished\\":\\"2026-11-14\\",\\"dateModified\\":\\"2026-11-15\\"},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Главная\\",\\"item\\":\\"https://omnicraft-erp.com/ru/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Статьи и руководства\\",\\"item\\":\\"https://omnicraft-erp.com/ru/articles/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Толщина кожи для изделий\\",\\"item\\":\\"https://omnicraft-erp.com/ru/articles/tolshchina-kozhi-dlya-izdelij\\"}]}]}"],["meta",{"property":"article:published_time","content":"2026-11-14"}],["meta",{"property":"article:modified_time","content":"2026-11-15"}]]},"headers":[],"relativePath":"ru/articles/tolshchina-kozhi-dlya-izdelij.md","filePath":"ru/articles/tolshchina-kozhi-dlya-izdelij.md"}'),i={name:"ru/articles/tolshchina-kozhi-dlya-izdelij.md"};function d(e,t,l,n,c,p){return a(),s("div",null,[...t[0]||(t[0]=[o('<div class="article-breadcrumb"><a href="/ru/articles/">← Все статьи и руководства</a></div><h1 id="толщина-кожи-для-кошелька-сумки-и-ремня-справочник-мастера-таблица-подбора-и-перевод-унции" tabindex="-1">Толщина кожи для кошелька, сумки и ремня: справочник мастера, таблица подбора и перевод унций <a class="header-anchor" href="#толщина-кожи-для-кошелька-сумки-и-ремня-справочник-мастера-таблица-подбора-и-перевод-унции" aria-label="Permalink to &quot;Толщина кожи для кошелька, сумки и ремня: справочник мастера, таблица подбора и перевод унций&quot;">​</a></h1><div class="craft-metaphor-card"><div class="metaphor-badge">Ловушка миллиметра</div><p class="metaphor-lead"> Кожа ведёт себя не как фанера или металл: в ней лишние две десятых миллиметра на выкройке кармана способны превратить элегантный бифолд в несгибаемый деревянный брусок толщиной в три сантиметра. Напротив, попытка сшить вместительный шоппер из мягкого хрома толщиной в один миллиметр неизбежно приводит к мешковине, которая плывёт под собственным весом фурнитуры. </p><div class="metaphor-grid"><div class="metaphor-col"><div class="metaphor-col-title">Иллюзия новичка</div><p>«Чем толще кожа, тем добротнее и солиднее вещь. Возьму на весь кошелёк плотный краст 1.8 мм, чтобы служил вечно».</p></div><div class="metaphor-col"><div class="metaphor-col-title">Инженерная реальность</div><p>В сложенном кошельке на боковом шве сходятся от четырех до шести слоев кожи. Без шерфования суммарный шов достигает 9–11 мм, нить рвёт край, а карты не входят в слоты.</p></div></div></div><p>Мастера регулярно сталкиваются с парадоксом: шкура заказана по паспорту артикула, резка выполнена строго по лекалу, а готовое изделие либо не держит форму, либо выглядит грубым и перегруженным.</p><p>Причина кроется в непонимании баланса между <strong>толщиной</strong>, <strong>темпером (жесткостью)</strong> и <strong>структурой дубления</strong>. В этом руководстве мы разберём конструктивные стандарты подбора сырья под 11 ключевых изделий, переведём зарубежные унции (<code>oz</code>) в метрическую систему, рассчитаем физику слоёного шва и покажем, как контролировать разнотолщинность шкуры на складе мастерской.</p><hr><h2 id="_1-фундаментальное-правило-толщина-не-равна-жесткости" tabindex="-1">1. Фундаментальное правило: толщина не равна жесткости <a class="header-anchor" href="#_1-фундаментальное-правило-толщина-не-равна-жесткости" aria-label="Permalink to &quot;1. Фундаментальное правило: толщина не равна жесткости&quot;">​</a></h2><p>Самое частое заблуждение при дистанционной закупке кожи — оценивать каркасность будущего изделия исключительно по толщиномеру:</p><div class="craft-spec-box"><div class="spec-box-title">Физика волокна: растительное против хромового дубления</div><p> Плотная кожа растительного дубления толщиной <strong>1.2 мм</strong> держит заданную геометрию клапана и ребер жесткости значительно строже, чем хромовый флоттер толщиной <strong>2.0 мм</strong>. Хромовое дубление разделяет и смазывает коллагеновые пучки, делая лист эластичным и текучим. Растительные танины связывают белковые спирали в монолитную пространственную решётку. </p></div><p>В профессиональном кожевенном деле сырьё классифицируется по трём базовым градациям жесткости (<em>Temper</em>):</p><ol class="craft-ordered-list"><li><div><strong>Мягкая кожа:</strong> легко драпируется, сминается в кулаке без заломов, не держит вертикальную грань (наппа, одёжный шевро, мягкий флоттер, замша, свиной велюр). <em>Назначение:</em> подкладка, мешочные выворотки, внутренняя драпировка сумок, перчатки. </div></li><li><div><strong>Полужесткая и средняя кожа:</strong> пружинит при сгибании, держит форму плоского листа, но плавно поддаётся формовке под собственным весом (галантерейный краст, пулл-ап, сафьяно, юфть среднего жирования). <em>Назначение:</em> наружные обложки кошельков, лонгеры, мягкие сумки с каркасными кедерами, папки для документов. </div></li><li><div><strong>Жесткая кожа:</strong> не прогибается в горизонтальном консольном вылете, держит ребро при ударе, отлично формуется на мокрую (чепраки и воротки растительного дубления, шорно-седельные кожи, подошвенный чепрак). <em>Назначение:</em> классические брючные и портупейные ремни, формованные ножны, кобуры, жесткие портфели-дипломаты. </div></li></ol><p>Если для каркасной сумки выбрана полужесткая кожа толщиной 1.4 мм, мастер обязан либо дублировать стенки кожкартоном (сальпой), либо проектировать конструкцию с переходом в растишку 2.0 мм.</p><hr><h2 id="_2-сводная-матрица-толщин-по-типам-изделии" tabindex="-1">2. Сводная матрица толщин по типам изделий <a class="header-anchor" href="#_2-сводная-матрица-толщин-по-типам-изделии" aria-label="Permalink to &quot;2. Сводная матрица толщин по типам изделий&quot;">​</a></h2><p>Конструкция качественного изделия всегда строится по принципу разгрузки узлов: на лицевую обложку закладывается защитный каркасный слой, а внутреннее наполнение утончается, чтобы снизить общий вес и толщину пакета.</p><table class="craft-matrix-table"><thead><tr><th style="width:20%;">Изделие</th><th style="width:25%;">Лицевая часть (каркас)</th><th style="width:25%;">Внутренние детали / карманы</th><th style="width:30%;">Рекомендуемый тип кожи и темпер</th></tr></thead><tbody><tr><td><strong>Кардхолдер</strong></td><td>1.0 – 1.2 мм (2.5–3 oz)</td><td>0.8 – 1.0 мм (2–2.5 oz)</td><td>Плотная растишка или коза (Medium/Firm). Спуск карманов до 0.5 мм обязателен.</td></tr><tr><td><strong>Кошелёк / Бифолд</strong></td><td>1.4 – 1.6 мм (3.5–4 oz)</td><td>0.8 – 1.0 мм (2–2.5 oz)</td><td>Лицо: краст, растишка, пулл-ап. Внутренности: утончённый краст или подклад 0.6 мм.</td></tr><tr><td><strong>Лонгер / Портмоне</strong></td><td>1.4 – 1.8 мм (3.5–4.5 oz)</td><td>0.8 – 1.0 мм (2–2.5 oz)</td><td>Лицевая панель требует стабильности геометрии; перегородки купюрниц — 0.8 мм.</td></tr><tr><td><strong>Обложка на паспорт</strong></td><td>1.2 – 1.4 мм (3–3.5 oz)</td><td>0.8 – 1.0 мм (2–2.5 oz)</td><td>Слишком толстая обложка деформирует страницы документа при закрытии.</td></tr><tr><td><strong>Сумка мягкая (шоппер, тоут)</strong></td><td>1.4 – 1.8 мм (3.5–4.5 oz)</td><td>0.6 – 0.8 мм (подкладка)</td><td>Хромовый краст, пулл-ап, наппа (Soft/Medium). Донышко усиливается вторым слоем.</td></tr><tr><td><strong>Сумка жесткая / Портфель</strong></td><td>2.0 – 2.4 мм (5–6 oz)</td><td>1.0 – 1.2 мм (2.5–3 oz)</td><td>Растительное дубление (Firm). Стенки держат форму без провисания замков.</td></tr><tr><td><strong>Ручки и ремни сумок</strong></td><td>2.8 – 3.5 мм (7–9 oz)</td><td>—</td><td>Чепрачная полоса продольного кроя в 1 слой либо склейка 2 слоёв по 1.6 мм.</td></tr><tr><td><strong>Ремень классический (костюмный)</strong></td><td>2.8 – 3.2 мм (7–8 oz)</td><td>— (или 2 слоя по 1.4 мм)</td><td>Плотный чепрак растительного дубления либо двухслойная склейка с прошивкой под узкую классическую пряжку 30–32 мм. Ремень толще 3.4 мм не входит в рамку костюмной пряжки и заламывает шлевки шерстяных брюк.</td></tr><tr><td><strong>Ремень повседневный (casual / джинсы)</strong></td><td>3.6 – 4.0 мм (9–10 oz)</td><td>—</td><td>Чепрак растительного дубления продольного хребтового кроя под массивную пряжку 38–40 мм.</td></tr><tr><td><strong>Ремень тяжелый (джинсы, портупея)</strong></td><td>4.2 – 5.0 мм (11–12 oz)</td><td>—</td><td>Шорно-седельный чепрак. Толщина менее 4.0 мм неизбежно вытягивается в отверстиях язычка под весом навесного снаряжения.</td></tr><tr><td><strong>Ножны, кобуры, чехлы топоров</strong></td><td>3.0 – 4.0 мм (7.5–10 oz)</td><td>Вкладыш (проставка): 3–4 мм</td><td>Строго жесткая растишка (Hard Firm) с глубокой мокрой формовкой по клину.</td></tr></tbody></table><h3 id="шпаргалка-мастера-популярные-артикулы-кожи-их-темпер-и-поведение-в-раскрое" tabindex="-1">Шпаргалка мастера: популярные артикулы кожи, их темпер и поведение в раскрое <a class="header-anchor" href="#шпаргалка-мастера-популярные-артикулы-кожи-их-темпер-и-поведение-в-раскрое" aria-label="Permalink to &quot;Шпаргалка мастера: популярные артикулы кожи, их темпер и поведение в раскрое&quot;">​</a></h3><p>Выбирая толщину, мастер обязан ориентироваться на конкретный коммерческий артикул: два куска кожи одинаковой толщины 1.4 мм ведут себя в раскрое и сборке диаметрально противоположно:</p><table class="craft-matrix-table"><thead><tr><th style="width:22%;">Артикул / Вид</th><th style="width:23%;">Дубление и темпер</th><th style="width:20%;">Рабочая толщина</th><th style="width:35%;">Поведение в раскрое и сборке</th></tr></thead><tbody><tr><td><strong>Buttero / Pueblo</strong> (Италия)</td><td>Растительное, Firm / Hard</td><td>0.9 – 2.0 мм</td><td>Монолитная плотная дерма, идеальная геометрия ребра. Держит форму в карманах даже при толщине 0.9 мм без дублирования. При заглаживании уреза даёт стеклянный глянец.</td></tr><tr><td><strong>Crazy Horse</strong></td><td>Хромовое с восковой пропиткой, Medium / Soft</td><td>1.4 – 1.8 мм</td><td>Выраженный пулл-ап эффект (осветление на сгибах). Из-за текучести требует припуска по толщине (+0.2 мм) или дублирования карманов кожкартоном/сальпой. При шерфовании нож должен быть бритвенно острым.</td></tr><tr><td><strong>Галантерейный краст</strong></td><td>Комбинированное, Regular / Medium</td><td>1.2 – 1.5 мм</td><td>Универсальный стандарт мастерской. Баланс формоустойчивости и пластичности. Легко шерфуется ручным ножом, отлично держит форму бифолдов и клапанов сумок.</td></tr><tr><td><strong>Шора / Юфть</strong></td><td>Жировое / комбинированное, Soft / Medium</td><td>1.8 – 2.4 мм</td><td>Высокая водостойкость и износостойкость. Волокна пластичны, склонна к тягучести. Оптимальна для чехлов, ножен с деревянным вкладышем и мягких дорожных сумок.</td></tr><tr><td><strong>Наппа / Шевро</strong></td><td>Хромовое, Soft Temper</td><td>0.7 – 1.1 мм</td><td>Шелковистая, текучая кожа без собственной каркасности. Используется исключительно для премиальной подкладки, обтяжки жестких каркасов либо с полным дублированием кожкартоном 0.4 мм.</td></tr></tbody></table><hr><h2 id="_3-таблица-перевода-унции-oz-в-миллиметры" tabindex="-1">3. Таблица перевода унций (oz) в миллиметры <a class="header-anchor" href="#_3-таблица-перевода-унции-oz-в-миллиметры" aria-label="Permalink to &quot;3. Таблица перевода унций (oz) в миллиметры&quot;">​</a></h2><p>При работе с зарубежными выкройками (США, Япония, Южная Корея) или покупке итальянской кожи европейские фабрики и лекальщики часто маркируют толщину в унциях (<code>oz</code>).</p><p>В кожевенном ремесле унция обозначает вес одного квадратного фута сырья, что при средней плотности натурального дермального слоя пересчитывается по простому эмпирическому правилу:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Коэффициент перевода</span><div class="formula-heading">Метрический эквивалент кожевенной унции (1 oz = 1/64 дюйма)</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">1 oz</span><span class="math-op">≈</span><span class="math-var">0.4 мм</span><span class="math-op">±</span><span class="math-num">0.05 мм</span></div></div><div class="formula-card-bottom"><p>Кожа всегда имеет технологический допуск, поэтому партии маркируют интервалами (например, 3/4 oz или 8/9 oz).</p></div></div><table class="craft-matrix-table"><thead><tr><th style="width:25%;">Маркировка в унциях (oz)</th><th style="width:25%;">Толщина в миллиметрах (мм)</th><th style="width:50%;">Типовое назначение в мастерской</th></tr></thead><tbody><tr><td><strong>1 – 2 oz</strong></td><td>0.4 – 0.8 мм</td><td>Тонкий подклад кошельков, обтяжка пластиковых каркасов, кант.</td></tr><tr><td><strong>2 – 3 oz</strong></td><td>0.8 – 1.2 мм</td><td>Внутренние слоты для пластиковых карт, перегородки купюрниц.</td></tr><tr><td><strong>3 – 4 oz</strong></td><td>1.2 – 1.6 мм</td><td>Лицевые панели бифолдов, обложки паспортов, чехлы телефонов.</td></tr><tr><td><strong>4 – 5 oz</strong></td><td>1.6 – 2.0 мм</td><td>Стенки легких сумок, рюкзаки, клапаны мягких портфелей.</td></tr><tr><td><strong>5 – 6 oz</strong></td><td>2.0 – 2.4 мм</td><td>Корпуса дорожных сумок, папки для документов, планшеты.</td></tr><tr><td><strong>6 – 7 oz</strong></td><td>2.4 – 2.8 мм</td><td>Лямки рюкзаков, легкие ремешки, чехлы для инструмента.</td></tr><tr><td><strong>7 – 8 oz</strong></td><td>2.8 – 3.2 мм</td><td>Силовые ручки сумок, узкие женские ремни, ножны.</td></tr><tr><td><strong>8 – 9 oz</strong></td><td>3.2 – 3.6 мм</td><td>Классический мужской брючный ремень, ошейники собак.</td></tr><tr><td><strong>9 – 10 oz</strong></td><td>3.6 – 4.0 мм</td><td>Джинсовые ремни с массивной пряжкой, чехлы топоров.</td></tr><tr><td><strong>10 – 12 oz</strong></td><td>4.0 – 4.8 мм</td><td>Тяжелые оружейные ремни, кобуры, рабочая упряжь.</td></tr></tbody></table><div class="download-banner"><div class="download-info"><div class="download-title">Единый шаблон расчёта расхода и себестоимости кожи в Excel</div><div class="download-desc">Готовые формулы без макросов: подставьте толщину кожи, площадь лекал и цену сырья — таблица автоматически рассчитает смету и потери на обрезки.</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;"><a href="/downloads/omnicraft_leather_cost_calculator.xlsx" download="ОмниКрафт_Калькулятор_раскроя_и_себестоимости_кожи.xlsx" class="vp-button brand" data-omni-event="article_download_leather_xlsx"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg><span>Скачать шаблон Excel (.xlsx)</span></a></div></div><hr><h2 id="_4-математика-«слоеного-пирога»-почему-шерфование-обязательно" tabindex="-1">4. Математика «слоёного пирога»: почему шерфование обязательно <a class="header-anchor" href="#_4-математика-«слоеного-пирога»-почему-шерфование-обязательно" aria-label="Permalink to &quot;4. Математика «слоёного пирога»: почему шерфование обязательно&quot;">​</a></h2><p>Главная ошибка сборки объемных изделий — суммирование номинальных толщин слоев без учета клеевого шва и физики огибания.</p><p>Разберём классический двухстворчатый кошелёк (бифолд). Конструкция включает:</p><ul><li>Наружную обложку;</li><li>Внутреннюю подкладку купюрного отсека;</li><li>Две стенки кассет под карты;</li><li>По три кармана для карт с каждой стороны (где каждый карман накладывается на предыдущий).</li></ul><p>На боковом шве, где пробивается строчка, сходятся:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Расчёт узла</span><div class="formula-heading">Математика шва бифолда (6 слоёв кожи)</div></div><div class="formula-equation-box"><div class="math-calc-stack"><div class="math-calc-row"><span class="math-calc-label">Пакет без шерфования:</span><span class="math-calc-expr">1.4 + 0.8 + 0.8 + (3 × 0.8) = <strong class="math-calc-result-danger">5.4 мм</strong></span><span class="math-calc-badge danger">(с клеем — 6.5 мм)</span></div><div class="math-calc-row"><span class="math-calc-label" style="color:#10b981;">После шерфования уреза:</span><span class="math-calc-expr">1.0 + 0.4 + 0.4 + (3 × 0.4) = <strong class="math-calc-result-success">3.0 мм</strong></span><span class="math-calc-badge success">(−54% толщины, эстетичный торец)</span></div></div></div><div class="formula-card-bottom"><p>Спуск края до 0.4 мм в зоне шва предотвращает эффект «распирающей пружины» при закрывании кошелька.</p></div></div><p>Прибавьте к этому толщину клеевой плёнки наирита или водного полиуретана (0.1–0.15 мм на слой) и микроскопический воздушный зазор между слоями. Суммарная толщина уреза на шве в собранном виде составит <strong>6.2–6.8 мм</strong>. Когда такой кошелёк закрывается пополам, в зоне сгиба толщина удвоится и превысит <strong>15 мм</strong> — кошелёк самопроизвольно раскрывается, словно пружина.</p><div class="craft-spec-box"><div class="spec-box-title">Технологический норматив спуска края: два профиля шерфования</div><p> Чтобы получить эстетичный торец и комфортную прошивку, мастер применяет два принципиально разных профиля спуска деталей: </p><ul><li><strong>Профиль А (Клин под открытый торец):</strong> карманы и подкладка спускаются по периметру на ширину <strong>6–8 мм</strong> от номинальных <strong>0.8–0.9 мм</strong> в теле детали до <strong>0.4–0.5 мм</strong> на самом краю. Т-образные карманы на боковых ушках утончаются в ноль;</li><li><strong>Профиль Б (Спуск под загибку / French Edge):</strong> верхние срезы карманов и борта сумок утончаются на ширину <strong>4–5 мм</strong> «в ноль» (до <strong>0.25–0.30 мм</strong>). После нанесения клея и подворота край детали имеет суммарную толщину ровно <strong>0.8–0.9 мм</strong> (номинал детали) — без образования ступеньки и уродливого валика, продавливающего лицевую обложку.</li></ul><p> В результате шерфования (обложка при легком спуске края до <strong>1.0–1.2 мм</strong> + подкладка <strong>0.4–0.5 мм</strong> + стенка <strong>0.4–0.5 мм</strong> + 3 спущенных кармана по <strong>0.4 мм</strong> + клеевые швы) толщина того же 6-слойного пакета на урезе падает с <strong>6.5 мм</strong> до комфортных <strong>3.2–3.6 мм</strong>. Шов легко пробивается строчным пробойником без увода геометрии зубьев, а готовый кошелёк свободно лежит в кармане брюк. </p></div><div class="craft-spec-box" style="margin:16px 0;"><div class="spec-box-title">Секрет мастера: стабилизация рыхлой бахтармы</div><p> При ручном спуске мягкого хрома или воскового пулл-апа нож часто тянет эластичные волокна, заминая деталь и рискуя прорезать её насквозь. <strong>Цеховой лайфхак:</strong> нанесите на зону спуска со стороны бахтармы тонкую полоску средства для уреза (Tokonole или слабый раствор КМЦ) и подождите 2 минуты до высыхания. Волокна временно схватятся в плотную плёнку, и брусовочный нож снимет идеально гладкую стружку на заданную толщину без единого задира. </p></div><p>Для калибровки толщины края применяют специализированный арсенал:</p><ul class="craft-feature-list"><li><div><strong>Японский косой нож (Nobiyoshi / Киридами):</strong> односторонняя заточка, идеален для широкого клиновидного спуска плотной растишки на полированном гранитном камне. </div></li><li><div><strong>Французский нож для шерфования:</strong> закругленная лопаткообразная пятка с контролируемой глубиной среза на пластичном хроме. </div></li><li><div><strong>Ручной рубанок для шерфования (Skife / Scharf-Fix):</strong> инструмент со сменными лезвиями для точной полосы спуска постоянной ширины. </div></li><li><div><strong>Брусовочная машина с чашечным ножом («Фортуна»):</strong> промышленный стандарт мастерских, позволяющий за секунды брусовать метры деталей сумок и ремней с точностью до 0.05 мм. </div></li></ul><hr><h2 id="_5-контроль-разнотолщинности-шкуры-и-учет-партии-на-складе" tabindex="-1">5. Контроль разнотолщинности шкуры и учёт партий на складе <a class="header-anchor" href="#_5-контроль-разнотолщинности-шкуры-и-учет-партии-на-складе" aria-label="Permalink to &quot;5. Контроль разнотолщинности шкуры и учёт партий на складе&quot;">​</a></h2><p>При заказе целой шкуры или полукожи на заводском ярлыке указывается средняя толщина (например, <code>1.4–1.6 мм</code>). Однако натуральная топография животного физиологически неравномерна:</p><div class="craft-spec-box"><div class="spec-box-title">Топографическая карта толщин и плотности полукожи</div><div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(200px, 1fr));gap:12px;margin-top:14px;"><div style="padding:12px 14px;border-radius:10px;background:var(--vp-c-bg);border:1px solid var(--vp-c-border);"><div style="font-size:0.75rem;font-weight:700;text-transform:uppercase;color:var(--vp-c-text-3);">Хребтовая линия</div><div style="font-size:1.05rem;font-weight:700;color:var(--vp-c-brand-1);margin:4px 0;">1.6 мм</div><div style="font-size:0.85rem;color:var(--vp-c-text-2);">Максимальная плотность, нулевая тягучесть. Силовая ось.</div></div><div style="padding:12px 14px;border-radius:10px;background:var(--vp-c-bg);border:1px solid var(--vp-c-border);border-left:3px solid #10b981;"><div style="font-size:0.75rem;font-weight:700;text-transform:uppercase;color:#10b981;">Чепрак (Золотой фонд)</div><div style="font-size:1.05rem;font-weight:700;color:var(--vp-c-text-1);margin:4px 0;">1.5 – 1.6 мм</div><div style="font-size:0.85rem;color:var(--vp-c-text-2);">Монолитная дерма без дефектов. Лицевые детали, ремни.</div></div><div style="padding:12px 14px;border-radius:10px;background:var(--vp-c-bg);border:1px solid var(--vp-c-border);"><div style="font-size:0.75rem;font-weight:700;text-transform:uppercase;color:var(--vp-c-text-3);">Огузок</div><div style="font-size:1.05rem;font-weight:700;color:var(--vp-c-text-1);margin:4px 0;">1.6 – 1.7 мм</div><div style="font-size:0.85rem;color:var(--vp-c-text-2);">Жесткий, плотный участок. Ножны, подошва, кобуры.</div></div><div style="padding:12px 14px;border-radius:10px;background:var(--vp-c-bg);border:1px solid var(--vp-c-border);border-left:3px solid #f59e0b;"><div style="font-size:0.75rem;font-weight:700;text-transform:uppercase;color:#f59e0b;">Вороток</div><div style="font-size:1.05rem;font-weight:700;color:var(--vp-c-text-1);margin:4px 0;">1.4 – 1.5 мм</div><div style="font-size:0.85rem;color:var(--vp-c-text-2);">Рыхлая структура, полосы роста. Внутренние узлы.</div></div><div style="padding:12px 14px;border-radius:10px;background:var(--vp-c-bg);border:1px solid var(--vp-c-border);border-left:3px solid #ef4444;"><div style="font-size:0.75rem;font-weight:700;text-transform:uppercase;color:#ef4444;">Пола (Брюшная зона)</div><div style="font-size:1.05rem;font-weight:700;color:var(--vp-c-text-1);margin:4px 0;">1.1 – 1.3 мм</div><div style="font-size:0.85rem;color:var(--vp-c-text-2);">Текучая, тянется на 15%. Мелкие карманы, образцы.</div></div></div></div><p>Разница между плотным чепраком у хребта и брюшной полой достигает <strong>0.3–0.5 мм</strong> (до 35% толщины листа). Если мастер без замера раскроит партию ремней или ответственных деталей сумки через переход от чепрака к поле, край ремня неизбежно деформируется при натяжении.</p><div class="craft-spec-box"><div class="spec-box-title">Регламент приёмки сырья: контрольный замер в 5 точках</div><p> При распаковке рулона мастер выполняет входной контроль механическим стрелочным или цифровым толщиномером с глубиной скобы от 150 мм: </p><ol class="craft-ordered-list"><li><div><strong>Точка 1 (Центр чепрака):</strong> базовая паспортная толщина партии (SSOT артикула). </div></li><li><div><strong>Точка 2 (Вдоль хребтовой линии):</strong> зона максимальной плотности и минимальной растяжимости. </div></li><li><div><strong>Точка 3 (Вороток):</strong> проверка рыхлости и утолщения (часто требует двоения). </div></li><li><div><strong>Точки 4 и 5 (Верхняя и нижняя границы полы):</strong> фиксация границы отреза неликвидных участков. </div></li></ol></div><div class="craft-spec-box" style="margin:16px 0;"><div class="spec-box-title">Метрологическая ловушка: почему нельзя мерить кожу штангенциркулем</div><p> Типичная ошибка начинающего мастера — замер толщины стандартным слесарным штангенциркулем. Острые и узкие губки инструмента под усилием пальцев сминают пористую структуру дермы на <strong>0.15–0.30 мм</strong>: лист реальной толщины 1.4 мм на шкале ошибочно покажет 1.15 мм. Погрешность вскроется только на сборке, когда швы откажутся сходиться. </p><p> По стандарту (ГОСТ 938.15-70 / ГОСТ ISO 2589-2023) замер кожи выполняют <strong>индикаторным толщиномером с плоской дисковой пятой диаметром не менее 10 мм</strong> и тарированным усилием прижима (около 50 кПа). Широкая пята распределяет давление по плоскости и замеряет истинную толщину материала без деформации структуры. </p></div><div class="craft-spec-box"><div class="spec-box-title">Физика кроя: силовая ось вдоль хребтовой линии</div><p> Натуральная кожа анизотропна: пучки коллагена ориентированы вдоль позвоночника животного. Продольный крой вдоль хребта даёт минимальное удлинение под нагрузкой (коэффициент деформации <strong>ε &lt; 3%</strong>) — именно так кроятся брючные ремни, плечевые ремни и ручки сумок. Поперечный раскрой (от хребта к поле) имеет коэффициент удлинения <strong>10–15%</strong>: выкроенный поперек ремень вытянется на 5–8 см за первые же недели носки. </p></div><p>В профессиональных мастерских эти параметры не хранятся в голове раскройщика. При оприходовании шкуры в <a href="/ru/docs/resources/warehouse">ОмниКрафт ЕРП</a> партия регистрируется с указанием диапазона толщин, типа дубления и площади.</p><p>Когда мастер формирует технологическую карту (BOM) на заказ, программа проверяет соответствие сырья: она физически не позволит списать партию с толщиной 1.2 мм на изделие, требующее по спецификации силовой ременной чепрак 3.8 мм.</p><hr><h2 id="_6-главныи-чек-лист-мастера-5-правил-подбора-кожи-перед-раскроем" tabindex="-1">6. Главный чек-лист мастера: 5 правил подбора кожи перед раскроем <a class="header-anchor" href="#_6-главныи-чек-лист-мастера-5-правил-подбора-кожи-перед-раскроем" aria-label="Permalink to &quot;6. Главный чек-лист мастера: 5 правил подбора кожи перед раскроем&quot;">​</a></h2><div class="craft-summary-card"><div class="summary-card-header"><span class="summary-badge">Шпаргалка мастера</span><div class="summary-title">Финальный производственный алгоритм выбора сырья</div><p class="summary-subtitle">Сконцентрированные правила для защиты изделия от брака, провисания и лишней толщины швов:</p></div><ol class="craft-ordered-list"><li><div><strong>Оценивайте темпер, а не только показания толщиномера:</strong><br> Мягкая хромовая кожа 2.0 мм провиснет в сумке-тоуте быстрее, чем сухой плотный чепрак растительного дубления 1.4 мм. Жёсткость и формоустойчивость конструкции задаются плотностью дермы и химией дубления, а не номинальной толщиной.<br><a href="#_1-фундаментальное-правило-толщина-не-равна-жесткости" class="summary-anchor-link"><span>Раздел 1: Физика темпера и свойства</span><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"></line><polyline points="5 12 12 5 19 12"></polyline></svg></a></div></li><li><div><strong>Всегда рассчитывайте суммарную толщину пакета в шве:</strong><br> Если на боковом урезе сходятся 3 и более слоёв — шерфование краёв до 0.4–0.5 мм строго обязательно. Спуск края снимает до 50% лишней толщины шва, защищает иглу от поломки и предотвращает эффект «распирающей пружины» при закрывании кошелька.<br><a href="#_4-математика-«слоеного-пирога»-почему-шерфование-обязательно" class="summary-anchor-link"><span>Раздел 4: Математика шва и шерфование</span><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"></line><polyline points="5 12 12 5 19 12"></polyline></svg></a></div></li><li><div><strong>Разделяйте продольный и поперечный раскрой шкуры:</strong><br> Силовые детали (ремни, ручки сумок, портупеи) кроятся строго вдоль хребтовой линии, где растяжение волокон не превышает 2–3%. Поперечный раскрой приведёт к деформации и вытягиванию ремня на 5–8 см уже в первые недели носки.<br><a href="#_5-контроль-разнотолщинности-шкуры-и-учет-партии-на-складе" class="summary-anchor-link"><span>Раздел 5: Топография шкуры и силовая ось</span><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"></line><polyline points="5 12 12 5 19 12"></polyline></svg></a></div></li><li><div><strong>Замеряйте толщину только дисковой пятой, а не штангенциркулем:</strong><br> Узкие губки слесарного штангенциркуля сминают бахтарму и занижают реальную толщину на 0.2–0.3 мм. Используйте индикаторный толщиномер с широкой плоской пятой диаметром от 10 мм и делайте замеры минимум в 10–15 см от края листа.<br><a href="#_5-контроль-разнотолщинности-шкуры-и-учет-партии-на-складе" class="summary-anchor-link"><span>Раздел 5: Правильный замер по стандарту</span><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"></line><polyline points="5 12 12 5 19 12"></polyline></svg></a></div></li><li><div><strong>Фиксируйте допуски сырья в спецификации изделия (BOM):</strong><br> Не держите диапазоны толщин в голове. Привязка номинала кожи к деталям технологической карты гарантирует, что на силовой ремень не спишут тонкую полукожу, а внутренние карманы не раздуют кошелёк до состояния кирпича.<br><a href="#_5-контроль-разнотолщинности-шкуры-и-учет-партии-на-складе" class="summary-anchor-link"><span>Раздел 5: Учёт партий и технологические карты</span><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="19" x2="12" y2="5"></line><polyline points="5 12 12 5 19 12"></polyline></svg></a></div></li></ol></div><hr><h2 id="_7-ответы-на-частые-вопросы-мастеров-faq" tabindex="-1">7. Ответы на частые вопросы мастеров (FAQ) <a class="header-anchor" href="#_7-ответы-на-частые-вопросы-мастеров-faq" aria-label="Permalink to &quot;7. Ответы на частые вопросы мастеров (FAQ)&quot;">​</a></h2><div class="craft-faq-accordion"><details class="faq-item"><summary class="faq-summary">Можно ли сшить ремень из тонкой кожи (2.0–2.5 мм), если проклеить её в два слоя?</summary><div class="faq-content"><p> Да, это классическая европейская технология создания двухслойных ремней с подкладом. Однако склеивать слои «лицо к лицу» нельзя: между ними обязательно прокладывается стабилизирующая армирующая лента (нейлоновая тесьма или безан), которая предотвращает продольное вытягивание. Верхний и нижний слои кроятся вдоль хребтовой линии. Суммарный ремень толщиной 3.8–4.2 мм с аккуратной строчкой по периметру служит дольше монолитного чепрака и выглядит изящнее. </p></div></details><details class="faq-item"><summary class="faq-summary">Какую толщину кожи выбрать для первого кошелька, если нет станка для двоения?</summary><div class="faq-content"><p> Оптимальный выбор для старта без профессионального оборудования — сухой галантерейный краст комбинированного или растительного дубления толщиной строго <strong>1.2–1.3 мм</strong>. Это компромиссная толщина: она достаточно стабильна для лицевой обложки небольшого кошелька и при этом допускает ручной спуск края на карманах канцелярским или японским ножом без риска прорезать деталь насквозь. </p></div></details><details class="faq-item"><summary class="faq-summary">Что делать, если купленная полукожа оказалась слишком толстой для проекта?</summary><div class="faq-content"><p> Есть три пути: 1) Отдать шкуру на двоильно-ленточный станок в местный кожевенный цех или магазин (услуга двоения листа или прохода на машине типа Camoga стоит 200–500 ₽, а при покупке кожи в магазине часто оказывается бесплатно); 2) Использовать химическое размягчение и проглаживание утюгом через пергамент с изнанки (уплотняет бахтарму и снимает 0.1 мм); 3) Зарезервировать эту шкуру под более крупные изделия, а на текущий проект оприходовать подходящую партию. </p></div></details><details class="faq-item"><summary class="faq-summary">Зависит ли выбор шага пробойника от толщины кожи?</summary><div class="faq-content"><p> Напрямую. Чем толще сшиваемый пакет, тем шире должен быть шаг строчного пробойника: для тонких кардхолдеров толщиной 2–3 мм используют шаг 2.7–3.38 мм; для сумок и бифолдов толщиной 4–6 мм — шаг 3.85–4.0 мм; для тяжелых ремней и ножен толщиной от 7 мм — шаг 5.0 мм. Если пробить толстый ремень мелким шагом 3.0 мм, частые отверстия превратятся в перфорационную ленту и кожа лопнет по линии шва при изгибе. Подробный расчёт длины нити на шаг пробойника разобран в нашей статье о <a href="/ru/articles/sedelnyj-shov-po-kozhe">седельном шве</a>. </p></div></details><details class="faq-item"><summary class="faq-summary">Как проверить толщину кожи, если под рукой нет дискового толщиномера?</summary><div class="faq-content"><p> Ни в коем случае не зажимайте кожу узкими губками штангенциркуля напрямую — острые грани сомнут дерму на 0.2–0.3 мм. Используйте метод эталонных пластин: положите край кожи между двумя плоскими жесткими пластинами (или монетами) известной толщины, аккуратно замерьте суммарный «бутерброд» штангенциркулем без сильного сдавливания и вычтите толщину пластин. Твердые плоскости распределят прижимное усилие по площади и предохранят волокна от продавливания. </p></div></details></div><hr><div class="cta-grid"><div class="cta-card featured-cta"><div><div class="cta-card-badge brand-badge">Склад и технологические карты</div><h3>ОмниКрафт ЕРП для кожевников</h3><p> Учитывайте партии шкур по толщинам, сорту и площади. Формируйте спецификации изделий (BOM) с автоматическим контролем списания материалов. До 20 заказов в месяц — бесплатно. </p></div><a href="/ru/docs/getting-started" class="vp-button brand cta-icon-btn" data-omni-event="article_cta_try_omnicraft" data-omni-data="tolshchina-kozhi-dlya-izdelij"><span>Попробовать бесплатно</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="cta-card"><div><div class="cta-card-badge">Инструмент мастера</div><h3>Калькулятор себестоимости кожи</h3><p> Рассчитайте себестоимость изделия с учётом толщины сырья, полезной площади раскроя, нормы расхода и коэффициента обрезков. </p></div><a href="/ru/calculators/leather-cost-calculator" class="vp-button alt cta-icon-btn" data-omni-event="article_cta_leather_calc" data-omni-data="tolshchina-kozhi-dlya-izdelij"><span>Открыть калькулятор</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div></div><hr><h2 id="связанные-статьи-производственного-кластера" tabindex="-1">Связанные статьи производственного кластера <a class="header-anchor" href="#связанные-статьи-производственного-кластера" aria-label="Permalink to &quot;Связанные статьи производственного кластера&quot;">​</a></h2><ul><li><a href="/ru/articles/lovushka-obrezkov-raskroj-kozhi">Ловушка обрезков: как на самом деле делать раскрой кожи и считать полезную площадь</a> — анатомическая карта шкуры (чепрак, вороток, пола), матрица КИС, 10 правил раскроя и эффективная цена полезного дециметра.</li><li><a href="/ru/articles/rashod-kozhi-na-izdeliya">Расход кожи: формула расчёта и нормы на сумку, кошелёк, ремень</a> — справочник точных норм расхода в дм² и фут² по 9 видам галантереи, весовой замер лекал и формула КИС.</li><li><a href="/ru/articles/chto-delat-s-obrezkami-kozhi">Что делать с обрезками кожи: 5 способов монетизации и учёт деловых остатков</a> — сортировка лоскута на 3 фракции, матрица быстрой микрогалантереи, продажа наборов и правило 6 месяцев.</li><li><a href="/ru/calculators/leather-cost-calculator">Калькулятор себестоимости изделий из кожи онлайн</a> — расчёт сметы с учётом потерь раскроя, химии уреза, амортизации и стоимости часа мастера.</li><li><a href="/ru/articles/pricing-and-margins">Ценообразование, наценка и маржа: как не работать в минус</a> — расчёт розничной цены от себестоимости и контроль точки безубыточности мастерской.</li></ul>',59)])])}const g=r(i,[["render",d]]);export{h as __pageData,g as default};
